public boolean hasNonNullAnnotationsOn(JavacNode node) {
	this.annotationScanNode = node;
	this.annotationScanInput = null;
	this.annotationScanMatch = null;
	this.annotationScanHit = false;
	this.annotationScanTypeName = null;
	if (node == null) return false;
	for (JavacNode child : node.down()) {
		if (child.getKind() != Kind.ANNOTATION) continue;
		JCAnnotation annotation = (JCAnnotation) child.get();
		if (annotationTypeNameMatchesNonNull(node, annotation)) {
			this.annotationScanMatch = annotation;
			this.annotationScanHit = true;
			return true;
		}
	}
	return false;
}

public boolean hasNonNullAnnotationsIn(JavacNode node, List<JCAnnotation> anns) {
	this.annotationScanNode = node;
	this.annotationScanInput = anns;
	this.annotationScanMatch = null;
	this.annotationScanHit = false;
	this.annotationScanTypeName = null;
	if (anns == null) return false;
	for (JCAnnotation ann : anns) {
		if (annotationTypeNameMatchesNonNull(node, ann)) {
			this.annotationScanMatch = ann;
			this.annotationScanHit = true;
			return true;
		}
	}
	return false;
}

private boolean annotationTypeNameMatchesNonNull(JavacNode node, JCAnnotation annotation) {
	if (annotation == null || annotation.annotationType == null) return false;
	this.annotationScanTypeName = annotation.annotationType.toString();
	for (String nn : NONNULL_ANNOTATIONS) {
		if (typeMatches(nn, node, annotation.annotationType)) return true;
	}
	return false;
}

public List<JCAnnotation> findCopyableAnnotationsFor(JavacNode node) {
	this.annotationScanNode = node;
	this.annotationScanMatch = null;
	this.annotationScanHit = false;
	JCAnnotation anno = null;
	String annoName = null;
	for (JavacNode child : node.down()) {
		if (child.getKind() != Kind.ANNOTATION) continue;
		if (anno != null) {
			annoName = "";
			break;
		}
		JCAnnotation annotation = (JCAnnotation) child.get();
		annoName = annotation.annotationType.toString();
		anno = annotation;
	}
	if (annoName == null) return List.nil();
	java.util.List<lombok.core.configuration.TypeName> configuredCopyable = node.getAst().readConfiguration(ConfigurationKeys.COPYABLE_ANNOTATIONS);
	if (!annoName.isEmpty()) {
		for (lombok.core.configuration.TypeName cn : configuredCopyable) {
			if (cn != null && typeMatches(cn.toString(), node, anno.annotationType)) {
				this.annotationScanMatch = anno;
				this.annotationScanHit = true;
				return List.of(anno);
			}
		}
		for (String bn : BASE_COPYABLE_ANNOTATIONS) {
			if (typeMatches(bn, node, anno.annotationType)) {
				this.annotationScanMatch = anno;
				this.annotationScanHit = true;
				return List.of(anno);
			}
		}
	}
	ListBuffer<JCAnnotation> result = new ListBuffer<JCAnnotation>();
	for (JavacNode child : node.down()) {
		if (child.getKind() != Kind.ANNOTATION) continue;
		JCAnnotation annotation = (JCAnnotation) child.get();
		String annotationTypeName = annotation.annotationType.toString();
		this.annotationScanTypeName = annotationTypeName;
		boolean match = false;
		for (lombok.core.configuration.TypeName cn : configuredCopyable) {
			if (cn != null && typeMatches(cn.toString(), node, annotation.annotationType)) {
				result.append(annotation);
				match = true;
				break;
			}
		}
		if (!match) {
			for (String bn : BASE_COPYABLE_ANNOTATIONS) {
				if (typeMatches(bn, node, annotation.annotationType)) {
					result.append(annotation);
					break;
				}
			}
		}
	}
	return result.toList();
}

public List<JCAnnotation> findCopyableToSetterAnnotationsFor(JavacNode node) {
	this.annotationScanNode = node;
	return findAnnotationsInKnownList(node, COPY_TO_SETTER_ANNOTATIONS);
}

private List<JCAnnotation> findAnnotationsInKnownList(JavacNode node, java.util.List<String> annotationsToFind) {
	this.annotationScanNode = node;
	JCAnnotation anno = null;
	String annoName = null;
	for (JavacNode child : node.down()) {
		if (child.getKind() != Kind.ANNOTATION) continue;
		if (anno != null) {
			annoName = "";
			break;
		}
		JCAnnotation annotation = (JCAnnotation) child.get();
		annoName = annotation.annotationType.toString();
		anno = annotation;
	}
	if (annoName == null) return List.nil();
	if (!annoName.isEmpty()) {
		for (String bn : annotationsToFind) {
			if (typeMatches(bn, node, anno.annotationType)) {
				this.annotationScanMatch = anno;
				this.annotationScanHit = true;
				return List.of(anno);
			}
		}
	}
	ListBuffer<JCAnnotation> result = new ListBuffer<JCAnnotation>();
	for (JavacNode child : node.down()) {
		if (child.getKind() != Kind.ANNOTATION) continue;
		JCAnnotation annotation = (JCAnnotation) child.get();
		for (String bn : annotationsToFind) {
			if (typeMatches(bn, node, annotation.annotationType)) {
				result.append(annotation);
				break;
			}
		}
	}
	return result.toList();
}

public void createRelevantNonNullAnnotationForMethod(JavacNode typeNode, JCMethodDecl method) {
	this.annotationScanNode = typeNode;
	NullAnnotationLibrary lib = typeNode.getAst().readConfiguration(ConfigurationKeys.ADD_NULL_ANNOTATIONS);
	if (lib == null) return;
	applyAnnotationToMethodDeclFor(typeNode, method, lib.getNonNullAnnotation(), lib.isTypeUse());
}

